            let reference = { () -> SIMD<UInt32>.HalfVector in
                var a = a
                return withUnsafeTemporaryAllocation(of: SIMD<UInt32>.HalfVector.self, capacity: 1)
                { result in
                    unsafe highwayHalfVectorResizingQuarterBF16ToU32InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        resizing: &a
